"""Video-MME family dataset loaders for local benchmarks."""

from __future__ import annotations

import logging
import re
from dataclasses import dataclass, field
from pathlib import Path

from datasets import load_dataset
from huggingface_hub import snapshot_download

logger = logging.getLogger(__name__)

DEFAULT_REPO_ID = "zhaochenyang20/Video_MME"
DEFAULT_VIDEOAMME_REPO_ID = "zhaochenyang20/Video_AMME_ci"
DEFAULT_VIDEOAMME_SOURCE_REPO_ID = "zhaochenyang20/Video_MME_ci"
VIDEOMME_DECODE_INVALID_VIDEO_PATHS = {
    "videos/5LU_XY0z2ZY.mp4",
    "videos/5kmnEgBSCfg.mp4",
    "videos/9Y-YJEtxHeo.mp4",
    "videos/MYxL_JLseC8.mp4",
    "videos/bHt0Riqz0qo.mp4",
    "videos/j27UP4zz_6U.mp4",
    "videos/jRS9fVh7MUw.mp4",
    "videos/vzfTpidE5wg.mp4",
}


@dataclass
class VideoMMESample:
    sample_id: str
    video_path: str
    question: str
    options: list[str]
    answer: str
    url: str = ""
    video_id: str = ""
    question_id: str = ""
    duration: str = "short"
    domain: str = "unknown"
    task_type: str = "understanding"
    sub_category: str = ""
    prompt: str = ""
    all_choices: list[str] = field(default_factory=list)
    index2ans: dict[str, str] = field(default_factory=dict)


@dataclass
class VideoAMMESample(VideoMMESample):
    audio_path: str = field(kw_only=True)


def _strip_option_prefix(option: str) -> str:
    return re.sub(r"^[A-D]\.\s*", "", option.strip())


def format_videomme_prompt(question: str, options: list[str]) -> str:
    from benchmarks.tasks.visual_understand import MULTI_CHOICE_INSTRUCTION

    prompt = f"{question.strip()}\n"
    for index, option in enumerate(options):
        letter = chr(ord("A") + index)
        prompt += f"{letter}. {option}\n"
    prompt += MULTI_CHOICE_INSTRUCTION
    return prompt


def _snapshot_dir(repo_id: str) -> Path:
    local_path = Path(repo_id).expanduser()
    if local_path.exists():
        return local_path
    return Path(snapshot_download(repo_id=repo_id, repo_type="dataset"))


def _resolve_video_path(snapshot_dir: Path, row: dict, question_id: str) -> str | None:
    relative_path = row.get("video_path")
    if not relative_path:
        logger.warning(
            f"Skipping Video-MME sample {question_id} because the dataset row has no video_path",
        )
        return None
    absolute_path = snapshot_dir / str(relative_path)
    if not absolute_path.exists():
        logger.warning(
            f"Skipping Video-MME sample {question_id} because the video file does not exist at {absolute_path}"
        )
        return None
    return str(absolute_path)


def _resolve_videoamme_audio_path(
    snapshot_dir: Path, row: dict, sample_id: str
) -> str | None:
    relative_path = row.get("audio_path")
    if not relative_path:
        logger.warning("Skipping Video-AMME sample %s without audio_path", sample_id)
        return None

    audio_path = snapshot_dir / str(relative_path)
    if not audio_path.exists():
        logger.warning(
            "Skipping Video-AMME sample %s because audio file is missing at %s",
            sample_id,
            audio_path,
        )
        return None
    return str(audio_path)


def _resolve_videoamme_video_path(
    snapshot_dir: Path,
    row: dict,
    sample_id: str,
    source_snapshots: dict[str, Path],
) -> str | None:
    local_relative_path = row.get("video_path")
    if local_relative_path:
        local_video_path = snapshot_dir / str(local_relative_path)
        if local_video_path.exists():
            return str(local_video_path)

    source_repo_id = str(
        row.get("source_repo_id") or DEFAULT_VIDEOAMME_SOURCE_REPO_ID
    ).strip()
    source_video_path = str(row.get("source_video_path") or "").strip()
    if not source_video_path:
        logger.warning(
            "Skipping Video-AMME sample %s without source_video_path", sample_id
        )
        return None

    if source_repo_id not in source_snapshots:
        source_snapshots[source_repo_id] = _snapshot_dir(source_repo_id)
    video_path = source_snapshots[source_repo_id] / source_video_path
    if not video_path.exists():
        logger.warning(
            "Skipping Video-AMME sample %s because source video is missing at %s",
            sample_id,
            video_path,
        )
        return None
    return str(video_path)


def _build_sample_kwargs(row, *, question_id: str, video_path: str) -> dict:
    options = [_strip_option_prefix(str(option)) for option in row["options"]]
    all_choices = [chr(ord("A") + i) for i in range(len(options))]
    index2ans = {choice: option for choice, option in zip(all_choices, options)}
    question = str(row["question"]).strip()
    return {
        "sample_id": question_id,
        "video_path": video_path,
        "question": question,
        "options": options,
        "answer": str(row["answer"]).strip(),
        "url": str(row.get("url", "")).strip(),
        "video_id": str(row.get("video_id", "")).strip(),
        "question_id": question_id,
        "duration": str(row.get("duration", "short")).strip(),
        "domain": str(row.get("domain", "unknown")).strip(),
        "task_type": str(row.get("task_type", "understanding")).strip(),
        "sub_category": str(row.get("sub_category", "")).strip(),
        "prompt": format_videomme_prompt(question, options),
        "all_choices": all_choices,
        "index2ans": index2ans,
    }


def _dataset_to_samples(dataset, *, max_samples: int | None, build_sample):
    samples: list[VideoMMESample] = []
    for row_index, row in enumerate(dataset):
        sample = build_sample(row_index, row)
        if sample is None:
            continue
        samples.append(sample)
        if max_samples is not None and len(samples) >= max_samples:
            break

    return samples


def _load_metadata_dataset(snapshot_dir: Path, split: str):
    data_dir = snapshot_dir / "data"
    split_parts = sorted(data_dir.glob(f"{split}_part_*.jsonl"))
    if split_parts:
        return load_dataset(
            "json",
            data_files=[str(path) for path in split_parts],
            split="train",
        )

    split_file = data_dir / f"{split}.jsonl"
    if split_file.exists():
        return load_dataset("json", data_files=str(split_file), split="train")

    available = sorted(path.name for path in data_dir.glob("*.jsonl"))
    raise ValueError(
        f"Split '{split}' not found under {data_dir}. Available files: {available}"
    )


def load_videomme_samples(
    max_samples: int | None = None,
    *,
    repo_id: str | None = None,
    split: str = "test",
) -> list[VideoMMESample]:
    resolved_repo_id = repo_id or DEFAULT_REPO_ID
    snapshot_dir = Path(
        snapshot_download(repo_id=resolved_repo_id, repo_type="dataset")
    )
    dataset = _load_metadata_dataset(snapshot_dir, split)

    def build_sample(row_index, row):
        question_id = str(row.get("question_id", f"videomme:{row_index}")).strip()
        relative_video_path = str(row.get("video_path") or "").strip()
        normalized_video_path = relative_video_path.removeprefix("./")
        if normalized_video_path in VIDEOMME_DECODE_INVALID_VIDEO_PATHS:
            logger.warning(
                f"Skipping Video-MME sample {question_id} because "
                f"{relative_video_path} is decode-invalid in the dataset",
            )
            return None
        video_path = _resolve_video_path(snapshot_dir, row, question_id)
        if not video_path:
            return None
        return VideoMMESample(
            **_build_sample_kwargs(row, question_id=question_id, video_path=video_path)
        )

    samples = _dataset_to_samples(
        dataset,
        max_samples=max_samples,
        build_sample=build_sample,
    )
    logger.info(f"Loaded {len(samples)} Video-MME samples")
    return samples


def load_videoamme_samples(
    max_samples: int | None = None,
    *,
    repo_id: str | None = None,
    split: str = "test",
) -> list[VideoAMMESample]:
    resolved_repo_id = repo_id or DEFAULT_VIDEOAMME_REPO_ID
    snapshot_dir = _snapshot_dir(resolved_repo_id)
    dataset = _load_metadata_dataset(snapshot_dir, split)
    source_snapshots: dict[str, Path] = {}

    def build_sample(row_index, row):
        question_id = str(row.get("question_id", f"videoamme:{row_index}")).strip()
        audio_path = _resolve_videoamme_audio_path(snapshot_dir, row, question_id)
        video_path = _resolve_videoamme_video_path(
            snapshot_dir,
            row,
            question_id,
            source_snapshots,
        )
        if not audio_path or not video_path:
            return None
        return VideoAMMESample(
            **_build_sample_kwargs(row, question_id=question_id, video_path=video_path),
            audio_path=audio_path,
        )

    samples = _dataset_to_samples(
        dataset,
        max_samples=max_samples,
        build_sample=build_sample,
    )
    logger.info("Loaded %d Video-AMME samples", len(samples))
    return samples

package compose

import (
	"strings"
	"testing"
)

// TestExample: speech with clean-up gets the example turn, in the main
// language's set, its answer in the target language when the set has
// it; a selection, Rewrite or no clean-up get none.
func TestExample(t *testing.T) {
	for _, c := range []struct {
		in     Input
		answer string // a part of the answer, "" for no example
	}{
		{Input{Task: Transcribe, Cleanup: true, MainLanguage: "zh"}, "发给小李，今天下班前"},
		{Input{Task: Transcribe, Cleanup: true, MainLanguage: "en"}, "to Anna before 5"},
		{Input{Task: Transcribe, Cleanup: true, MainLanguage: "fr"}, "to Anna before 5"},
		{Input{Task: Transcribe, MainLanguage: "zh"}, ""},
		{Input{Task: Translate, Cleanup: true, MainLanguage: "zh", TargetLanguage: "en"}, "Xiao Li before the end of today"},
		{Input{Task: Translate, Cleanup: true, MainLanguage: "zh", TargetLanguage: "zh-Hans"}, "发给小李"},
		{Input{Task: Translate, Cleanup: true, MainLanguage: "en", TargetLanguage: "zh-Hans"}, "把周报发给 Anna"},
		{Input{Task: Translate, Cleanup: true, MainLanguage: "en", TargetLanguage: "en-GB"}, "to Anna before 5"},
		{Input{Task: Translate, Cleanup: true, MainLanguage: "zh", TargetLanguage: "ja"}, ""},
		{Input{Task: Translate, Cleanup: true, MainLanguage: "zh", TargetLanguage: "zh-Hant"}, ""},
		{Input{Task: Translate, Cleanup: true, Selected: true, MainLanguage: "zh", TargetLanguage: "en"}, ""},
		{Input{Task: Rewrite, Cleanup: true, MainLanguage: "zh", Instruction: "x"}, ""},
	} {
		c.in.Text = "x"
		_, answer, ok := Example(c.in)
		out, err := Build(c.in)
		if err != nil {
			t.Fatal(err)
		}
		if c.answer == "" {
			if ok || len(out.History) != 0 {
				t.Errorf("%+v: an example %q", c.in, answer)
			}
			continue
		}
		if !ok || !strings.Contains(answer, c.answer) {
			t.Errorf("%+v: example %q, want %q", c.in, answer, c.answer)
		}
		if len(out.History) != 2 || out.History[0].Role != "user" || !strings.HasPrefix(out.History[0].Content, "<input>") ||
			out.History[1].Role != "assistant" || out.History[1].Content != answer {
			t.Errorf("%+v: history %+v", c.in, out.History)
		}
		if m := out.Messages(); len(m) != 4 || m[3].Content != UserMessage("x") {
			t.Errorf("messages %+v", m)
		}
	}
}

package main

import (
	"encoding/binary"
	"fmt"
	"math"
)

const (
	outRate   = 16000
	trimLevel = 0.001 // -60 dBFS
	padSecs   = 0.3
	peakLevel = 0.7079457843841379 // -3 dBFS
	sincHalf  = 32                 // taps on each side, at the lower rate
)

// readWAV reads a mono WAV of 16-bit PCM or 32-bit float samples.
func readWAV(b []byte) ([]float64, int, error) {
	if len(b) < 12 || string(b[:4]) != "RIFF" || string(b[8:12]) != "WAVE" {
		return nil, 0, fmt.Errorf("not a WAV file")
	}
	var format, channels, bits uint16
	var rate uint32
	for p := 12; p+8 <= len(b); {
		id, size := string(b[p:p+4]), int(binary.LittleEndian.Uint32(b[p+4:]))
		body := b[p+8 : min(p+8+size, len(b))]
		switch id {
		case "fmt ":
			if len(body) < 16 {
				return nil, 0, fmt.Errorf("short fmt chunk")
			}
			format, channels = binary.LittleEndian.Uint16(body), binary.LittleEndian.Uint16(body[2:])
			rate, bits = binary.LittleEndian.Uint32(body[4:]), binary.LittleEndian.Uint16(body[14:])
		case "data":
			if channels != 1 {
				return nil, 0, fmt.Errorf("%d channels, want mono", channels)
			}
			switch {
			case format == 1 && bits == 16:
				x := make([]float64, len(body)/2)
				for i := range x {
					x[i] = float64(int16(binary.LittleEndian.Uint16(body[2*i:]))) / 32768
				}
				return x, int(rate), nil
			case format == 3 && bits == 32:
				x := make([]float64, len(body)/4)
				for i := range x {
					x[i] = float64(math.Float32frombits(binary.LittleEndian.Uint32(body[4*i:])))
				}
				return x, int(rate), nil
			}
			return nil, 0, fmt.Errorf("format %d, %d bits: want 16-bit PCM or 32-bit float", format, bits)
		}
		p += 8 + size + size%2
	}
	return nil, 0, fmt.Errorf("no data chunk")
}

// process trims, resamples to outRate, pads and normalises x: its peak
// to -3 dBFS, then gain dB more; length (seconds) pads the end further.
func process(x []float64, rate int, gain, length float64) []float64 {
	from, to := 0, len(x)
	for from < to && math.Abs(x[from]) < trimLevel {
		from++
	}
	for to > from && math.Abs(x[to-1]) < trimLevel {
		to--
	}
	y := resample(x[from:to], rate, outRate)
	pad := int(padSecs * outRate)
	out := make([]float64, pad, len(y)+2*pad)
	out = append(out, y...)
	out = append(out, make([]float64, max(pad, int(length*outRate)-len(out)))...)
	peak := 0.0
	for _, v := range out {
		peak = max(peak, math.Abs(v))
	}
	if peak > 0 {
		for i := range out {
			out[i] *= peakLevel / peak * math.Pow(10, gain/20)
		}
	}
	return out
}

// resample converts x from rate in to rate out with a Blackman-windowed
// sinc, cut off a little under the lower rate's Nyquist frequency.
func resample(x []float64, in, out int) []float64 {
	if in == out {
		return append([]float64(nil), x...)
	}
	ratio := float64(in) / float64(out)
	cut := 0.95 * math.Min(1, 1/ratio) // of the input's Nyquist
	half := float64(sincHalf) / cut    // taps on each side, in input samples
	n := int(float64(len(x)) / ratio)
	y := make([]float64, n)
	for i := range y {
		t := float64(i) * ratio
		lo, hi := int(math.Ceil(t-half)), int(math.Floor(t+half))
		var sum float64
		for k := max(lo, 0); k <= min(hi, len(x)-1); k++ {
			d := t - float64(k)
			w := 0.42 + 0.5*math.Cos(math.Pi*d/half) + 0.08*math.Cos(2*math.Pi*d/half)
			sum += x[k] * cut * sinc(cut*d) * w
		}
		y[i] = sum
	}
	return y
}

func sinc(v float64) float64 {
	if v == 0 {
		return 1
	}
	return math.Sin(math.Pi*v) / (math.Pi * v)
}

// writeWAV is x as a 16-bit mono PCM WAV at outRate, with triangular
// dither from seed.
func writeWAV(x []float64, seed uint32) []byte {
	state := seed*2654435761 + 1
	rnd := func() float64 { // xorshift32, in [0, 1)
		state ^= state << 13
		state ^= state >> 17
		state ^= state << 5
		return float64(state) / (1 << 32)
	}
	data := make([]byte, 2*len(x))
	for i, v := range x {
		s := math.Round(v*32767 + rnd() - rnd())
		binary.LittleEndian.PutUint16(data[2*i:], uint16(int16(max(-32768, min(32767, s)))))
	}
	h := make([]byte, 44)
	copy(h, "RIFF")
	binary.LittleEndian.PutUint32(h[4:], uint32(36+len(data)))
	copy(h[8:], "WAVEfmt ")
	binary.LittleEndian.PutUint32(h[16:], 16)
	binary.LittleEndian.PutUint16(h[20:], 1)
	binary.LittleEndian.PutUint16(h[22:], 1)
	binary.LittleEndian.PutUint32(h[24:], outRate)
	binary.LittleEndian.PutUint32(h[28:], outRate*2)
	binary.LittleEndian.PutUint16(h[32:], 2)
	binary.LittleEndian.PutUint16(h[34:], 16)
	copy(h[36:], "data")
	binary.LittleEndian.PutUint32(h[40:], uint32(len(data)))
	return append(h, data...)
}

import { afterEach, expect, test } from "bun:test";
import {
  Channel,
  call,
  currentWindow,
  direction,
  event,
  isCallError,
  isMyGo,
  locale,
  on,
  onDocumentReload,
  onDocumentState,
  onFileDrop,
  onLocaleChange,
  onPreferences,
  preferences,
  runtime,
  type DocumentState,
  type FileDrop,
  type Runtime,
  type ThemePreferences,
} from "./index";

const calls: [string, unknown[]][] = [];
const listeners = new Map<string, (payload: unknown) => void>();

const fake: Runtime = {
  call: async <T>(method: string, ...args: unknown[]) => {
    calls.push([method, args]);
    if (method === "Svc.Fail") {
      const err = new Error("boom") as Error & { method: string };
      err.name = "CallError";
      err.method = method;
      throw err;
    }
    return method as T;
  },
  channel: <T>(onmessage?: (value: T) => void) =>
    ({ onmessage, onclose: null, closed: false, close() {}, [Symbol.asyncIterator]: () => ({}) }) as unknown as Channel<T>,
  on: (name, listener) => {
    listeners.set(name, listener as (payload: unknown) => void);
    return () => listeners.delete(name);
  },
  once: (name, listener) => {
    listeners.set(name, listener as (payload: unknown) => void);
    return () => listeners.delete(name);
  },
  platform: "darwin",
  windowId: 1,
  version: "0.1.0",
  preferences: { accent: null, reduceMotion: false, reduceTransparency: true, highContrast: false, textScale: 1 },
  locale: "en",
  dir: "ltr",
  window: {
    minimize: () => fake.call("mygo:window.Minimize"),
    maximize: () => fake.call("mygo:window.Maximize"),
    unmaximize: () => fake.call("mygo:window.Unmaximize"),
    toggleMaximize: () => fake.call("mygo:window.ToggleMaximize"),
    isMaximized: () => fake.call("mygo:window.IsMaximized"),
    toggleFullScreen: () => fake.call("mygo:window.ToggleFullScreen"),
    close: () => fake.call("mygo:window.Close"),
    setTitle: (title) => fake.call("mygo:window.SetTitle", title),
  },
};

afterEach(() => {
  delete (globalThis as { mygo?: Runtime }).mygo;
  calls.length = 0;
  listeners.clear();
});

test("outside MyGo", async () => {
  expect(isMyGo()).toBe(false);
  expect(() => runtime()).toThrow("runtime not found");
  await expect(call("Svc.Method")).rejects.toThrow("runtime not found");
});

test("delegates to window.mygo", async () => {
  (globalThis as { mygo?: Runtime }).mygo = fake;
  expect(isMyGo()).toBe(true);
  expect(await call<string>("Svc.Method", 1, "a")).toBe("Svc.Method");
  expect(calls).toEqual([["Svc.Method", [1, "a"]]]);

  const got: unknown[] = [];
  const off = event<{ n: number }>("tick").on((p) => got.push(p.n));
  listeners.get("tick")?.({ n: 7 });
  off();
  expect(got).toEqual([7]);
  expect(listeners.has("tick")).toBe(false);

  on("other", () => {});
  expect(listeners.has("other")).toBe(true);

  await currentWindow.setTitle("Hi");
  expect(calls.at(-1)).toEqual(["mygo:window.SetTitle", ["Hi"]]);

  const err = await call("Svc.Fail").catch((e: unknown) => e);
  expect(isCallError(err)).toBe(true);
  expect(isCallError(new Error("other"))).toBe(false);
});

test("Channel", () => {
  expect(() => new Channel()).toThrow("runtime not found");
  (globalThis as { mygo?: Runtime }).mygo = fake;
  const fn = (n: number) => n;
  const ch = new Channel<number>(fn);
  expect(ch.onmessage).toBe(fn);
  expect(ch.closed).toBe(false);
});

test("onFileDrop", () => {
  (globalThis as { mygo?: Runtime }).mygo = fake;
  const got: FileDrop[] = [];
  const off = onFileDrop((d) => got.push(d));
  listeners.get("mygo:file-drop")?.({ paths: ["/tmp/a.txt"], x: 10, y: 20 });
  expect(got).toEqual([{ paths: ["/tmp/a.txt"], x: 10, y: 20 }]);
  off();
  expect(listeners.has("mygo:file-drop")).toBe(false);
});

test("onDocumentState and onDocumentReload", () => {
  (globalThis as { mygo?: Runtime }).mygo = fake;
  const states: DocumentState[] = [];
  let reloads = 0;
  const off = onDocumentState((s) => states.push(s));
  const offReload = onDocumentReload(() => reloads++);
  const state = { name: "a.md", path: "/tmp/a.md", edited: true, readOnly: false, conflict: false, deleted: false };
  listeners.get("mygo:document-state")?.(state);
  listeners.get("mygo:document-reload")?.({});
  expect(states).toEqual([state]);
  expect(reloads).toBe(1);
  off();
  offReload();
  expect(listeners.has("mygo:document-state")).toBe(false);
  expect(listeners.has("mygo:document-reload")).toBe(false);
});

test("preferences and onPreferences", () => {
  (globalThis as { mygo?: Runtime }).mygo = fake;
  expect(preferences()).toEqual(fake.preferences);
  const got: ThemePreferences[] = [];
  const off = onPreferences((p) => got.push(p));
  const changed = { accent: "#ff8000", reduceMotion: true, reduceTransparency: false, highContrast: false, textScale: 1.25 };
  listeners.get("mygo:preferences")?.(changed);
  expect(got).toEqual([changed]);
  off();
  expect(listeners.has("mygo:preferences")).toBe(false);
});

test("locale, direction and onLocaleChange", () => {
  (globalThis as { mygo?: Runtime }).mygo = fake;
  expect(locale()).toBe("en");
  expect(direction()).toBe("ltr");
  const got: [string, string][] = [];
  const off = onLocaleChange((tag, dir) => got.push([tag, dir]));
  listeners.get("mygo:locale")?.({ locale: "ar", dir: "rtl" });
  expect(got).toEqual([["ar", "rtl"]]);
  off();
  expect(listeners.has("mygo:locale")).toBe(false);
});

